#include <any>
#include <print>
#include <string>

int main() {
    std::any p = 42, q = std::string{"Bishop"};
    std::println(
        "p: {}, q: {}", std::any_cast<int>(p), std::any_cast<std::string &>(q));
    std::println("swap(p, q)");
    std::swap(p, q);
    std::println(
        "p: {}, q: {}", std::any_cast<std::string &>(p), std::any_cast<int>(q));
}
